<?php
declare(strict_types=1);function x1_base32_encode(string $data):string{$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits='';foreach(str_split($data)as $c)$bits.=str_pad(decbin(ord($c)),8,'0',STR_PAD_LEFT);$out='';for($i=0;$i<strlen($bits);$i+=5){$chunk=substr($bits,$i,5);if(strlen($chunk)<5)$chunk=str_pad($chunk,5,'0');$out.=$alphabet[bindec($chunk)];}return $out;}function x1_base32_decode(string $s):string{$s=strtoupper(preg_replace('/[^A-Z2-7]/','',$s));$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits='';foreach(str_split($s)as $c){$p=strpos($alphabet,$c);if($p===false)continue;$bits.=str_pad(decbin($p),5,'0',STR_PAD_LEFT);}$out='';for($i=0;$i+8<=strlen($bits);$i+=8)$out.=chr(bindec(substr($bits,$i,8)));return $out;}function x1_totp_secret():string{return x1_base32_encode(random_bytes(20));}function x1_totp_code(string $secret,?int $time=null):string{$counter=intdiv($time??time(),30);$bin=pack('N*',0).pack('N*',$counter);$hash=hash_hmac('sha1',$bin,x1_base32_decode($secret),true);$o=ord($hash[19])&15;$num=((ord($hash[$o])&127)<<24)|((ord($hash[$o+1])&255)<<16)|((ord($hash[$o+2])&255)<<8)|(ord($hash[$o+3])&255);return str_pad((string)($num%1000000),6,'0',STR_PAD_LEFT);}function x1_totp_verify(string $secret,string $code,int $window=1):bool{$code=preg_replace('/\D/','',$code);if(strlen($code)!==6)return false;$now=time();for($i=-$window;$i<=$window;$i++)if(hash_equals(x1_totp_code($secret,$now+$i*30),$code))return true;return false;}